I am thinking about the following change (looking at the flags inside processPod):
```
diff --git a/pkg/scheduler/algorithm/priorities/interpod_affinity.go b/pkg/scheduler/algorithm/priorities/interpod_affinity.go
index 50737ed029..02a82fa455 100644
--- a/pkg/scheduler/algorithm/priorities/interpod_affinity.go
+++ b/pkg/scheduler/algorithm/priorities/interpod_affinity.go
@@ -109,8 +109,18 @@ func (ipa *InterPodAffinity) CalculateInterPodAffinityPriority(pod *v1.Pod, node
        lazyInit := hasAffinityConstraints || hasAntiAffinityConstraints
        for name := range nodeNameToInfo {
                allNodeNames = append(allNodeNames, name)
+               hasAffinityPods := false
+               for _, existingPod := range nodeNameToInfo[name].Pods() {
+                       existingPodAffinity := existingPod.Spec.Affinity
+                       existingHasAffinityConstraints := existingPodAffinity != nil && existingPodAffinity.PodAffinity != nil
+                       existingHasAntiAffinityConstraints := existingPodAffinity != nil && existingPodAffinity.PodAntiAffinity != nil
+                       if existingHasAffinityConstraints || existingHasAntiAffinityConstraints {
+                               hasAffinityPods = true;
+                               break
+                       }
+               }
                // if pod has affinity defined, or target node has affinityPods
-               if lazyInit || len(nodeNameToInfo[name].PodsWithAffinity()) != 0 {
+               if lazyInit || hasAffinityPods || len(nodeNameToInfo[name].PodsWithAffinity()) != 0 {
                        pm.counts[name] = new(int64)
                }
        }
```
Another option is to allocate int64 for every node.

@bernadinm Is it possible that your workload has Pod(Anti-)Affinity **explicitly** defined but its size is 0?

I asked this because it seems we only check if the Pod.Affinity.Pod(Anti-)Affinity == nil:

https://github.com/kubernetes/kubernetes/blob/09d2cdf384309696c01307d249bc308f87402d0a/pkg/scheduler/nodeinfo/node_info.go#L496-L499

How about the following change ?
```
diff --git a/pkg/scheduler/algorithm/priorities/interpod_affinity.go b/pkg/scheduler/algorithm/priorities/interpod_affinity.go
index 50737ed029..e830ba9b19 100644
--- a/pkg/scheduler/algorithm/priorities/interpod_affinity.go
+++ b/pkg/scheduler/algorithm/priorities/interpod_affinity.go
@@ -107,11 +107,28 @@ func (ipa *InterPodAffinity) CalculateInterPodAffinityPriority(pod *v1.Pod, node
        pm := newPodAffinityPriorityMap(nodes)
        allNodeNames := make([]string, 0, len(nodeNameToInfo))
        lazyInit := hasAffinityConstraints || hasAntiAffinityConstraints
+       emptyNodeCount := 0
+       affinityUsed := false
        for name := range nodeNameToInfo {
                allNodeNames = append(allNodeNames, name)
                // if pod has affinity defined, or target node has affinityPods
-               if lazyInit || len(nodeNameToInfo[name].PodsWithAffinity()) != 0 {
+               if lazyInit {
                        pm.counts[name] = new(int64)
+               } else if len(nodeNameToInfo[name].PodsWithAffinity()) != 0 {
+                       pm.counts[name] = new(int64)
+                       affinityUsed = true
+               } else {
+                       emptyNodeCount++
+               }
+       }
+       if affinityUsed && emptyNodeCount > 0 {
+               countArray := make([]int64, emptyNodeCount, emptyNodeCount)
+               i := 0
+               for name := range nodeNameToInfo {
+                       if len(nodeNameToInfo[name].PodsWithAffinity()) == 0 {
+                               pm.counts[name] = &countArray[i]
+                               i++
+                       }
                }
        }
```
